import { useMemo, useState } from 'react';
import { Activity, Archive, ArrowDownLeft, ArrowLeftRight, ArrowRight, ArrowUpRight, Bell, BookOpen, CalendarDays, Check, ChevronLeft, ChevronRight, CircleAlert, CreditCard as CreditCardIcon, Download, Eye, EyeOff, FileDown, FolderKanban, HeartHandshake, Landmark, ListFilter, Pencil, Plus, Repeat2, RotateCcw, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Trash2, Wallet, X } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { accountBalances, buildInvoices, currentBudgetUse, expensesByCategory, goalBalanceCents, isOverdue, monthTotals, netWorthCents } from '../domain/finance';
import { addMonthsKey, formatDate, monthLabel, monthKey, money, percent, todayISO } from '../lib/format';
import type { Account, AppSettings, Budget, BudgetRule, Category, CreditCard, Debt, Goal, Invoice, PlannedExpense, Receivable, RecurringItem, SavedFilter, Snapshot, Transaction, TrashItem } from '../types';
import type { ModalKind } from '../components/FormModal';
import TrashView from './TrashView';

export type Screen = 'dashboard'|'transactions'|'budget'|'planning'|'more'|'accounts'|'cards'|'recurring'|'debts'|'goals'|'receivables'|'calendar'|'trash'|'settings'|'categories'|'rules';
interface Data {
  transactions: Transaction[]; accounts: Account[]; cards: CreditCard[]; categories: Category[]; budgets: Budget[]; recurring: RecurringItem[];
  debts: Debt[]; goals: Goal[]; receivables: Receivable[]; planned: PlannedExpense[];
  rules: BudgetRule[]; filters: SavedFilter[]; snapshots: Snapshot[]; trash: TrashItem[]; settings?: AppSettings;
}
interface Props {
  screen: Screen; data: Data; month: string; privateMode: boolean; onMonthChange: (month:string)=>void;
  onNew: (kind:ModalKind, category?:Category)=>void; onImport:()=>void; onBackup:()=>void; onRestoreBackup:(file:File)=>void;
  onExportCsv:(items:Transaction[])=>void; onExportPdf:()=>void; onEditEntry:(entry:Transaction)=>void; onDeleteEntry:(entry:Transaction, all?:boolean)=>void;
  onPayEntry:(entry:Transaction)=>void; onPayInvoice:(invoice:Invoice)=>void; onReceive:(item:Receivable)=>void; onTogglePrivacy:()=>void;
  onTheme:(theme:'light'|'dark')=>void; onMonthStart:(day:number)=>void; onNotifications:()=>void; onArchiveAccount:(account:Account)=>void;
  onToggleRecurring:(item:RecurringItem)=>void; onCopyBudgets:()=>void; onSuggestBudgets:()=>void; onConvertPlan:(item:PlannedExpense)=>void;
  onRestore:(item:TrashItem)=>void; onPurgeTrash:()=>void; onSaveFilter:(name:string,filters:Record<string,string>)=>void; onDeleteFilter:(id:string)=>void;
  onCreateRule:(entry:Transaction)=>void; onDeleteRule:(rule:BudgetRule)=>void; onPayDebt:(debt:Debt)=>void; onArchiveCard:(card:CreditCard)=>void;
  onEditGoal:(goal:Goal)=>void; onDeleteGoal:(goal:Goal)=>void; onArchiveGoal:(goal:Goal)=>void;
  onNavigate:(screen:Screen)=>void;
}
const currency = (c:number, hidden:boolean) => money(c,hidden);
const formatShort = (m:string) => new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(new Date(Number(m.slice(0,4)),Number(m.slice(5,7))-1,1)).replace('.','');
const monthDays = (m:string) => new Date(Number(m.slice(0,4)),Number(m.slice(5,7)),0).getDate();
const categoryFor = (id:string|undefined,categories:Category[]) => categories.find(c=>c.id===id);
function PageTitle({eyebrow,title,desc,actions}:{eyebrow?:string;title:string;desc?:string;actions?:React.ReactNode}) {return <div className="page-title"><div>{eyebrow&&<p className="eyebrow">{eyebrow}</p>}<h1>{title}</h1>{desc&&<p className="muted">{desc}</p>}</div>{actions&&<div className="title-actions">{actions}</div>}</div>;}
function SectionTitle({title,action}:{title:string;action?:React.ReactNode}){return <div className="section-title"><h2>{title}</h2>{action}</div>;}
function Pill({children,tone='neutral'}:{children:React.ReactNode;tone?:string}){return <span className={`pill ${tone}`}>{children}</span>;}
function Empty({title,body,action}:{title:string;body:string;action?:React.ReactNode}){return <div className="empty-state"><div className="empty-symbol"><Wallet size={23}/></div><h3>{title}</h3><p>{body}</p>{action}</div>;}
function StatCard({label,value,sub,icon:Icon,tone='green',hidden=false}:{label:string;value:number;sub?:string;icon:LucideIcon;tone?:string;hidden?:boolean}){return <article className={`stat-card ${tone}`}><div className="stat-top"><span>{label}</span><span className="stat-icon"><Icon size={17}/></span></div><strong>{currency(value,hidden)}</strong>{sub&&<small>{sub}</small>}</article>;}
function MonthPicker({month,onChange}:{month:string;onChange:(v:string)=>void}){return <label className="month-picker"><button type="button" aria-label="Mês anterior" onClick={()=>onChange(addMonthsKey(month,-1))}><ChevronLeft size={17}/></button><input type="month" value={month} onChange={e=>onChange(e.target.value)}/><button type="button" aria-label="Próximo mês" onClick={()=>onChange(addMonthsKey(month,1))}><ChevronRight size={17}/></button></label>;}
function TxRow({tx,categories,hidden,onEdit,onDelete,onPay,onRule}:{tx:Transaction;categories:Category[];hidden:boolean;onEdit:()=>void;onDelete:()=>void;onPay:()=>void;onRule:()=>void}) {
  const [touchStart,setTouchStart]=useState(0); const cat=categoryFor(tx.categoryId,categories); const isIn=tx.kind==='income'||tx.kind==='reimbursement';
  return <article className="transaction-row" onTouchStart={e=>setTouchStart(e.changedTouches[0]?.clientX??0)} onTouchEnd={e=>{const delta=(e.changedTouches[0]?.clientX??touchStart)-touchStart;if(delta < -90&&tx.status!=='paid')onPay();else if(delta>90)onDelete();}}>
    <div className="tx-marker" style={{background:cat?.color??(isIn?'#4D9C72':'#E8E8E0')}}>{isIn?<ArrowDownLeft size={17}/>:tx.kind==='transfer'?<ArrowLeftRight size={17}/>:<ArrowUpRight size={17}/>}</div>
    <div className="tx-main"><strong>{tx.description}</strong><span>{formatDate(tx.date)}{cat?` · ${cat.name}`:''}{tx.installmentIndex?` · ${tx.installmentIndex}/${tx.installmentCount}`:''}</span></div>
    <div className="tx-amount"><strong className={isIn?'positive':tx.kind==='expense'?'negative':''}>{tx.kind==='expense'?'−':isIn?'+':''}{currency(tx.amountCents,hidden)}</strong><Pill tone={tx.status==='paid'?'success':isOverdue(tx)?'danger':'warning'}>{tx.status==='paid'?'Pago':isOverdue(tx)?'Atrasado':'Pendente'}</Pill></div>
    <div className="row-actions">{tx.attachment&&<button title="Abrir comprovante" className="icon-button" onClick={()=>{const url=URL.createObjectURL(tx.attachment!.blob);const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.click();window.setTimeout(()=>URL.revokeObjectURL(url),60000);}}>Anexo</button>}{tx.status!=='paid'&&<button title="Marcar como pago" className="icon-button" onClick={onPay}><Check size={16}/></button>}<button title="Criar regra de categoria" className="icon-button" onClick={onRule}><Sparkles size={15}/></button><button title="Editar" className="icon-button" onClick={onEdit}><Pencil size={15}/></button><button title="Excluir" className="icon-button danger-icon" onClick={onDelete}><Trash2 size={15}/></button></div>
  </article>;
}
function buildForecast(month:string,data:Data):{month:string;label:string;balance:number;income:number;expenses:number;negative:boolean}[] {
  const balances=accountBalances(data.accounts,data.transactions); let rolling=data.accounts.filter(a=>a.includeInTotal&&!a.archived).reduce((s,a)=>s+(balances[a.id]??0),0);
  const invoices=buildInvoices(data.cards,data.transactions);
  const out=[];
  for(let i=0;i<12;i++){
    const key=addMonthsKey(month,i); const transactions=data.transactions.filter(t=>!t.deletedAt&&t.date.startsWith(key)&&['income','expense','goalContribution','reimbursement'].includes(t.kind));
    let income=transactions.filter(t=>t.kind==='income').reduce((s,t)=>s+t.amountCents,0); let expenses=transactions.filter(t=>(t.kind==='expense'&&!t.cardId)||(t.kind==='goalContribution'&&!t.goalAccountId)).reduce((s,t)=>s+t.amountCents,0);
    for(const item of data.recurring.filter(r=>r.active)){
      const exists=transactions.some(t=>t.recurrenceId===item.id);
      if(!exists&&item.startDate<=`${key}-${String(monthDays(key)).padStart(2,'0')}`&&(!item.endDate||item.endDate>=`${key}-01`)){const perMonth={weekly:4.33,fortnightly:2.17,monthly:1,bimonthly:.5,quarterly:1/3,semiannual:1/6,annual:1/12}[item.frequency]; if(item.kind==='income')income+=Math.round(item.amountCents*perMonth);else expenses+=Math.round(item.amountCents*perMonth);}
    }
    for(const debt of data.debts.filter(d=>d.active)) if(!transactions.some(t=>t.recurrenceId===`debt:${debt.id}`)) expenses+=debt.installmentCents;
    expenses+=data.planned.filter(p=>p.month===key&&!p.convertedTransactionId).reduce((s,p)=>s+p.amountCents,0);
    for(const goal of data.goals)if(goal.automaticMonthlyCents&&!goal.accountId&&!transactions.some(t=>t.recurrenceId===`goal:${goal.id}`))expenses+=goal.automaticMonthlyCents;
    const dueInvoices=invoices.filter(inv=>inv.remainingCents>0&&(i===0?inv.dueDate<=`${key}-${String(monthDays(key)).padStart(2,'0')}`:inv.dueDate.startsWith(key))).reduce((s,inv)=>s+inv.remainingCents,0);
    expenses+=dueInvoices;
    if(i===0){const pending=data.transactions.filter(t=>!t.deletedAt&&t.status!=='paid'&&t.date.startsWith(key));income=pending.filter(t=>t.kind==='income').reduce((s,t)=>s+t.amountCents,0);expenses=pending.filter(t=>(t.kind==='expense'&&!t.cardId)||(t.kind==='goalContribution'&&!t.goalAccountId)).reduce((s,t)=>s+t.amountCents,0)+data.planned.filter(p=>p.month===key&&!p.convertedTransactionId).reduce((s,p)=>s+p.amountCents,0)+dueInvoices;for(const item of data.recurring.filter(r=>r.active&&r.startDate<=`${key}-${String(monthDays(key)).padStart(2,'0')}`&&(!r.endDate||r.endDate>=`${key}-01`)&&!pending.some(t=>t.recurrenceId===r.id))){const perMonth={weekly:4.33,fortnightly:2.17,monthly:1,bimonthly:.5,quarterly:1/3,semiannual:1/6,annual:1/12}[item.frequency];if(item.kind==='income')income+=Math.round(item.amountCents*perMonth);else expenses+=Math.round(item.amountCents*perMonth);}for(const debt of data.debts.filter(d=>d.active&&!pending.some(t=>t.recurrenceId===`debt:${d.id}`)))expenses+=debt.installmentCents;for(const goal of data.goals)if(goal.automaticMonthlyCents&&!goal.accountId&&!pending.some(t=>t.recurrenceId===`goal:${goal.id}`))expenses+=goal.automaticMonthlyCents;}
    rolling+=income-expenses;out.push({month:key,label:formatShort(key),balance:rolling,income,expenses,negative:rolling<0});
  }
  return out;
}

function Dashboard({data,month,hidden,onMonthChange,onNew,onPayEntry,onPayInvoice,onEditEntry,onDeleteEntry,onCreateRule,onImport,onExportPdf,onBackup,onTogglePrivacy}:{data:Data;month:string;hidden:boolean;onMonthChange:(v:string)=>void;onNew:(k:ModalKind)=>void;onPayEntry:(t:Transaction)=>void;onPayInvoice:(i:Invoice)=>void;onEditEntry:(t:Transaction)=>void;onDeleteEntry:(t:Transaction)=>void;onCreateRule:(t:Transaction)=>void;onImport:()=>void;onExportPdf:()=>void;onBackup:()=>void;onTogglePrivacy:()=>void}){
  const totals=monthTotals(data.transactions,month,data.receivables); const balances=accountBalances(data.accounts,data.transactions); const balance=data.accounts.filter(a=>a.includeInTotal&&!a.archived).reduce((s,a)=>s+(balances[a.id]??0),0); const invoices=buildInvoices(data.cards,data.transactions); const monthInvoices=invoices.filter(i=>i.month===month); const net=netWorthCents(data.accounts,balances,invoices,data.debts);
  const byCat=expensesByCategory(data.transactions,month,data.categories,data.receivables); const forecast=buildForecast(month,data);
  const accountSummary=data.accounts.filter(a=>!a.archived).map(a=>({account:a,balance:balances[a.id]??a.initialBalanceCents}));
  const cardSummary=data.cards.filter(c=>!c.archived).map(card=>({card,used:invoices.filter(i=>i.cardId===card.id).reduce((sum,i)=>sum+i.remainingCents,0)}));
  const receivableTotal=data.receivables.filter(r=>r.status!=='received').reduce((sum,r)=>sum+r.amountCents-r.receivedCents,0);
  const methodTotals=Object.entries(data.transactions.filter(t=>!t.deletedAt&&t.kind==='expense'&&t.date.startsWith(month)).reduce<Record<string,number>>((acc,t)=>{const key=t.paymentMethod??'other';acc[key]=(acc[key]??0)+t.amountCents;return acc;},{})).sort((a,b)=>b[1]-a[1]);
  const comparisons=data.categories.filter(c=>c.kind==='expense'&&!c.archived).map(category=>{const spend=(key:string)=>currentBudgetUse(data.transactions,key,category.id,data.receivables);const current=spend(month);const avg3=Math.round([-1,-2,-3].reduce((sum,n)=>sum+spend(addMonthsKey(month,n)),0)/3);const avg6=Math.round([-1,-2,-3,-4,-5,-6].reduce((sum,n)=>sum+spend(addMonthsKey(month,n)),0)/6);return {category,current,avg3,avg6,change:avg3?Math.round((current-avg3)*100/avg3):0};}).filter(x=>x.current||x.avg3||x.avg6).sort((a,b)=>b.current-a.current).slice(0,6);
  const netWorthHistory=[...data.snapshots].sort((a,b)=>a.month.localeCompare(b.month)).slice(-11).map(x=>({month:x.month,label:formatShort(x.month),value:x.netWorthCents/100}));if(!netWorthHistory.some(x=>x.month===month))netWorthHistory.push({month,label:formatShort(month),value:net/100});
  const trend=Array.from({length:12},(_,i)=>{const key=addMonthsKey(month,i-11);const t=monthTotals(data.transactions,key,data.receivables);return {month:key,label:formatShort(key),income:t.incomeCents/100,expenses:t.expensesCents/100,net:(t.incomeCents-t.expensesCents)/100};});
  const budgetBars=data.categories.filter(c=>c.kind==='expense'&&!c.archived).map(c=>({name:c.name,spent:currentBudgetUse(data.transactions,month,c.id,data.receivables)/100,budget:(data.budgets.find(b=>b.month===month&&b.categoryId===c.id)?.amountCents??0)/100,color:c.color})).filter(x=>x.spent>0||x.budget>0).slice(0,7);
  const daysLeft=monthDays(month)-new Date().getDate(); const insights:string[]=[];
  for(const c of data.categories.filter(c=>c.kind==='expense')){const budget=data.budgets.find(b=>b.month===month&&b.categoryId===c.id);if(budget){const spent=currentBudgetUse(data.transactions,month,c.id,data.receivables);if(budget.amountCents>0&&spent>budget.amountCents)insights.push(`${c.name} está ${Math.round((spent-budget.amountCents)*100/budget.amountCents)}% acima do orçamento.`);else if(budget.amountCents>0&&spent>=budget.amountCents*.8)insights.push(`${c.name}: ${percent(spent,budget.amountCents)}% do orçamento usado.`);}}
  for(const c of data.categories.filter(c=>c.kind==='expense')){const thisSpent=currentBudgetUse(data.transactions,month,c.id,data.receivables);const previous=currentBudgetUse(data.transactions,addMonthsKey(month,-1),c.id,data.receivables);if(previous>0&&Math.abs(thisSpent-previous)/previous>=.15){const p=Math.round(Math.abs(thisSpent-previous)*100/previous);insights.push(`Você gastou ${p}% ${thisSpent<previous?'menos':'mais'} com ${c.name.toLowerCase()} que no mês passado.`);}}
  for(const goal of data.goals){if(!goal.deadline)continue;const saved=goalBalanceCents(goal.id,data.transactions);const monthsLeft=Math.max(1,Math.ceil((new Date(goal.deadline).getTime()-Date.now())/(30*86400000)));const needed=Math.ceil(Math.max(0,goal.targetCents-saved)/monthsLeft);const actual=goal.automaticMonthlyCents??0;if(actual>0&&actual<needed){const delay=Math.ceil((goal.targetCents-saved)/actual)-monthsLeft;if(delay>0)insights.push(`No ritmo atual, a meta ${goal.name} pode atrasar ${delay} ${delay===1?'mês':'meses'}.`);}}
  if(data.debts.length){const income=totals.incomeCents;const monthlyDebt=data.debts.filter(d=>d.active).reduce((s,d)=>s+d.installmentCents,0);if(income>0)insights.push(`Suas dívidas consomem ${Math.round(monthlyDebt*100/income)}% da renda registrada neste mês.`);}
  const upcoming=data.transactions.filter(t=>!t.deletedAt&&t.status!=='paid'&&t.dueDate&&t.dueDate>=todayISO()&&t.dueDate<=new Date(Date.now()+7*86400000).toLocaleDateString('en-CA')).sort((a,b)=>(a.dueDate??'').localeCompare(b.dueDate??''));
  const dueInvoices=invoices.filter(i=>i.remainingCents>0&&i.dueDate>=todayISO()&&i.dueDate<=new Date(Date.now()+7*86400000).toLocaleDateString('en-CA'));
  const recent=data.transactions.filter(t=>!t.deletedAt&&t.date.startsWith(month)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
  return <div className="page-content"><div className="dashboard-head"><div><p className="eyebrow">PAINEL FINANCEIRO</p><h1>Seu dinheiro, sem surpresas.</h1><p className="muted">Um olhar claro para o que entrou, saiu e vem pela frente.</p></div><MonthPicker month={month} onChange={onMonthChange}/></div>
    <div className="balance-banner"><div><span className="banner-label">SALDO TOTAL</span><strong>{currency(balance,hidden)}</strong><small>Patrimônio líquido · {currency(net,hidden)}</small></div><div className="banner-actions"><button className="btn light" onClick={()=>onNew('entry')}><Plus size={17}/> Novo lançamento</button><button className="icon-button eye-button" onClick={onTogglePrivacy} aria-label="Privacidade"><ShieldCheck size={18}/></button></div><div className="banner-mark">◉</div></div>
    <div className="stats-grid"><StatCard label="Entradas" value={totals.incomeCents} sub={totals.pendingIncomeCents?`${currency(totals.pendingIncomeCents,hidden)} a receber`:undefined} icon={ArrowDownLeft} tone="green" hidden={hidden}/><StatCard label="Saídas" value={totals.expensesCents} icon={ArrowUpRight} tone="rose" hidden={hidden}/><StatCard label="Guardado" value={totals.savedCents} icon={Landmark} tone="lavender" hidden={hidden}/><StatCard label="A pagar" value={totals.pendingCents+monthInvoices.reduce((s,i)=>s+i.remainingCents,0)} icon={CalendarDays} tone="amber" hidden={hidden}/></div>
    <div className="overview-strip"><section className="panel overview-card"><strong>Saldo por conta</strong>{accountSummary.length?accountSummary.slice(0,4).map(({account,balance})=><div className="overview-row" key={account.id}><span><i style={{background:account.color}}/>{account.name}</span><b>{currency(balance,hidden)}</b></div>):<small className="muted">Cadastre sua primeira conta.</small>}</section><section className="panel overview-card"><strong>Limite disponível</strong>{cardSummary.length?cardSummary.slice(0,4).map(({card,used})=><div className="overview-row" key={card.id}><span>{card.name}</span><b>{currency(Math.max(0,card.limitCents-used),hidden)}</b></div>):<small className="muted">Nenhum cartão cadastrado.</small>}</section><section className="panel overview-card receivable-summary"><strong>A receber</strong><b className="overview-total">{currency(receivableTotal,hidden)}</b><small className="muted">Divisões e reembolsos pendentes</small></section></div>
    <div className="dashboard-grid"><section className="panel chart-panel"><SectionTitle title="Gastos por categoria" action={<span className="muted tiny">{monthLabel(month)}</span>}/>{byCat.length?<div className="donut-area"><ResponsiveContainer width="58%" height={220}><PieChart><Pie data={byCat} dataKey="amount" nameKey="name" innerRadius={61} outerRadius={88} paddingAngle={3} stroke="none">{byCat.map(c=><Cell key={c.id} fill={c.color}/>)}</Pie>{!hidden&&<Tooltip formatter={(v:number)=>money(v)}/>}</PieChart></ResponsiveContainer><div className="legend-list">{byCat.slice(0,5).map(c=><div className="legend-row" key={c.id}><i style={{background:c.color}}/><span>{c.name}</span><strong>{currency(c.amount,hidden)}</strong></div>)}</div></div>:<div className="chart-empty">Registre despesas para ver a distribuição por categoria.</div>}</section>
      <section className="panel chart-panel"><SectionTitle title="Gasto vs. orçamento" action={<span className="muted tiny">por categoria</span>}/>{budgetBars.length?<ResponsiveContainer width="100%" height={236}><BarChart data={budgetBars} layout="vertical" margin={{left:0,right:8,top:4,bottom:4}}><CartesianGrid strokeDasharray="3 3" horizontal={false}/><XAxis type="number" hide={hidden}/><YAxis type="category" dataKey="name" width={86} tick={{fontSize:11}}/><Tooltip formatter={(v:number)=>hidden?'••••':money(v)}/><Bar dataKey="budget" name="Orçamento" fill="#DADFD4" radius={[0,6,6,0]}/><Bar dataKey="spent" name="Gasto" fill="#2E755B" radius={[0,6,6,0]}/></BarChart></ResponsiveContainer>:<div className="chart-empty">Defina um orçamento para acompanhar seus limites.</div>}</section>
      <section className="panel chart-panel wide-panel"><SectionTitle title="Tendência mês a mês" action={<span className="muted tiny">últimos 12 meses</span>}/><ResponsiveContainer width="100%" height={242}><LineChart data={trend} margin={{left:8,right:12,top:10,bottom:0}}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="label" tick={{fontSize:11}}/><YAxis tickFormatter={v=>hidden?'••':`R$${v}`} tick={{fontSize:10}}/><Tooltip formatter={(v:number)=>hidden?'••••':money(Math.round(v*100))}/><Line type="monotone" dataKey="income" name="Receita" stroke="#4D9C72" strokeWidth={2.5} dot={false}/><Line type="monotone" dataKey="expenses" name="Despesa" stroke="#E0836A" strokeWidth={2.5} dot={false}/><Line type="monotone" dataKey="net" name="Saldo do mês" stroke="#8B77C8" strokeWidth={2} dot={false}/></LineChart></ResponsiveContainer></section>
      <section className="panel chart-panel wide-panel"><SectionTitle title="Saldo projetado" action={<span className="muted tiny">próximos 12 meses</span>}/><ResponsiveContainer width="100%" height={220}><LineChart data={forecast} margin={{left:8,right:12,top:10,bottom:0}}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="label" tick={{fontSize:11}}/><YAxis tickFormatter={v=>hidden?'••':money(v)} tick={{fontSize:10}}/><Tooltip formatter={(v:number)=>hidden?'••••':money(v)}/><Line type="monotone" dataKey="balance" name="Saldo projetado" stroke="#2E755B" strokeWidth={2.5} dot={{r:3}}/></LineChart></ResponsiveContainer>{forecast.some(x=>x.negative)&&<div className="forecast-strip">{forecast.filter(x=>x.negative).map(x=><span className="forecast-negative" key={x.month}><CircleAlert size={14}/>{monthLabel(x.month)} com saldo negativo projetado</span>)}</div>}</section>
      <section className="panel insights-panel"><SectionTitle title="Leituras do mês" action={<Sparkles size={17} className="accent-icon"/>}/>{insights.length?insights.slice(0,5).map((text,i)=><div className="insight" key={i}><span className="insight-dot"/>{text}</div>):<div className="insight"><span className="insight-dot"/>Registre movimentações e orçamentos para revelar tendências.</div>}<p className="helper-text">Análises calculadas no dispositivo a partir dos seus registros.</p></section>
      <section className="panel upcoming-panel"><SectionTitle title="Próximos 7 dias" action={<CalendarDays size={17}/>} />{upcoming.length||dueInvoices.length?<div className="upcoming-list">{upcoming.slice(0,4).map(tx=><div className="upcoming-item" key={tx.id}><span className="date-chip">{formatDate(tx.dueDate).slice(0,5)}</span><div><strong>{tx.description}</strong><small>{categoryFor(tx.categoryId,data.categories)?.name??'Vencimento'}</small></div><b>{currency(tx.amountCents,hidden)}</b><button className="icon-button" onClick={()=>onPayEntry(tx)} title="Marcar pago"><Check size={15}/></button></div>)}{dueInvoices.slice(0,2).map(i=><div className="upcoming-item" key={i.id}><span className="date-chip">{formatDate(i.dueDate).slice(0,5)}</span><div><strong>Fatura · {data.cards.find(c=>c.id===i.cardId)?.name}</strong><small>{i.status==='partial'?'Pagamento parcial':'Fatura'}</small></div><b>{currency(i.remainingCents,hidden)}</b><button className="icon-button" onClick={()=>onPayInvoice(i)} title="Pagar fatura"><Check size={15}/></button></div>)}</div>:<div className="chart-empty">Sem vencimentos próximos. Você tem {Math.max(0,daysLeft)} dias no mês para ajustar o ritmo.</div>}</section>
    </div>
    <div className="dashboard-grid"><section className="panel chart-panel"><SectionTitle title="Patrimônio líquido" action={<span className="muted tiny">snapshots locais</span>}/>{netWorthHistory.length>1?<ResponsiveContainer width="100%" height={210}><LineChart data={netWorthHistory}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="label" tick={{fontSize:10}}/><YAxis tickFormatter={v=>hidden?'••':`R$${v}`} tick={{fontSize:10}}/><Tooltip formatter={(v:number)=>hidden?'••••':money(Math.round(v*100))}/><Line dataKey="value" name="Patrimônio" stroke="#8B77C8" strokeWidth={2.5} dot={{r:3}}/></LineChart></ResponsiveContainer>:<div className="chart-empty">Os snapshots mensais aparecerão conforme o histórico for acumulado.</div>}</section><section className="panel chart-panel"><SectionTitle title="Gastos por forma de pagamento" action={<span className="muted tiny">{monthLabel(month)}</span>}/>{methodTotals.length?methodTotals.map(([key,value])=><div className="overview-row breakdown-row" key={key}><span>{({cash:'Dinheiro',pix:'Pix',debit:'Débito',credit:'Crédito',boleto:'Boleto',transfer:'Transferência',voucher:'Vale',other:'Outros'} as Record<string,string>)[key]??key}</span><b>{currency(value,hidden)}</b></div>):<div className="chart-empty">Ainda não há gastos registrados neste período.</div>}</section></div>
    <section className="panel comparison-panel"><SectionTitle title="Este mês vs. médias recentes" action={<span className="muted tiny">por categoria</span>}/>{comparisons.length?<div className="comparison-table"><div className="comparison-head"><span>Categoria</span><span>Este mês</span><span>Média 3m</span><span>Média 6m</span><span>vs. 3m</span></div>{comparisons.map(row=><div className="comparison-row" key={row.category.id}><span><i style={{background:row.category.color}}/>{row.category.name}</span><b>{currency(row.current,hidden)}</b><span>{currency(row.avg3,hidden)}</span><span>{currency(row.avg6,hidden)}</span><span className={row.change>0?'comparison-up':'comparison-down'}>{row.change>0?'+':''}{row.change}%</span></div>)}</div>:<div className="chart-empty">Com mais histórico, você verá aqui a comparação com as médias dos últimos 3 e 6 meses.</div>}</section>
    <section className="panel recent-panel"><SectionTitle title="Movimentações recentes" action={<button className="text-button" onClick={()=>onNew('entry')}>Ver e adicionar <ArrowRight size={14}/></button>}/>{recent.length?recent.map(tx=><TxRow key={tx.id} tx={tx} categories={data.categories} hidden={hidden} onEdit={()=>onEditEntry(tx)} onDelete={()=>onDeleteEntry(tx)} onPay={()=>onPayEntry(tx)} onRule={()=>onCreateRule(tx)}/>):<Empty title="Seu mês começa aqui" body="Adicione a primeira movimentação para acompanhar as entradas e despesas." action={<button className="btn primary" onClick={()=>onNew('entry')}><Plus size={16}/> Registrar movimentação</button>}/>}</section>
    <div className="dashboard-quick-actions"><button className="quick-link" onClick={()=>onNew('deposit')}><ArrowDownLeft size={17}/> Aportar à meta</button><button className="quick-link" onClick={onImport}><FileDown size={17}/> Importar extrato</button><button className="quick-link" onClick={onExportPdf}><Download size={17}/> Resumo em PDF</button><button className="quick-link" onClick={onBackup}><ShieldCheck size={17}/> Backup local</button></div>
  </div>;
}

function Transactions({data,month,hidden,onNew,onEditEntry,onDeleteEntry,onPayEntry,onCreateRule,onExportCsv,onSaveFilter,onDeleteFilter}:{data:Data;month:string;hidden:boolean;onNew:()=>void;onEditEntry:(t:Transaction)=>void;onDeleteEntry:(t:Transaction,all?:boolean)=>void;onPayEntry:(t:Transaction)=>void;onCreateRule:(t:Transaction)=>void;onExportCsv:(items:Transaction[])=>void;onSaveFilter:(name:string,filters:Record<string,string>)=>void;onDeleteFilter:(id:string)=>void}){
  const [q,setQ]=useState('');const [category,setCategory]=useState('');const [status,setStatus]=useState('');const [method,setMethod]=useState('');const [account,setAccount]=useState('');const [min,setMin]=useState('');const [max,setMax]=useState('');const [from,setFrom]=useState(`${month}-01`);const [to,setTo]=useState(`${month}-${String(monthDays(month)).padStart(2,'0')}`);const [showFilters,setShowFilters]=useState(false);
  const filtered=useMemo(()=>data.transactions.filter(t=>!t.deletedAt&&(!q||`${t.description} ${t.notes??''} ${t.tags.join(' ')}`.toLowerCase().includes(q.toLowerCase()))&&(!category||t.categoryId===category)&&(!status||(status==='overdue'?isOverdue(t):status==='pending'?t.status!=='paid':t.status===status))&&(!method||t.paymentMethod===method)&&(!account||t.accountId===account)&&(!from||t.date>=from)&&(!to||t.date<=to)&&(!min||t.amountCents>=Number(min)*100)&&(!max||t.amountCents<=Number(max)*100)),[data.transactions,q,category,status,method,account,from,to,min,max]);
  const save=()=>{const name=window.prompt('Nome para este filtro:');if(name)onSaveFilter(name,{q,category,status,method,account,from,to,min,max});};
  return <div className="page-content"><PageTitle eyebrow="SEU HISTÓRICO" title="Lançamentos" desc="Encontre, confira e organize cada movimentação." actions={<button className="btn primary" onClick={onNew}><Plus size={17}/> Novo</button>}/>
    <section className="panel filters-panel"><div className="search-row"><div className="search-field"><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar descrição, observação ou tag"/><button className="icon-button" onClick={()=>setShowFilters(v=>!v)} title="Mais filtros"><SlidersHorizontal size={16}/></button></div><button className="btn secondary" onClick={save}><ListFilter size={15}/> Salvar filtro</button><button className="btn secondary" onClick={()=>onExportCsv(filtered)}><Download size={15}/> CSV</button></div>
      <div className={`filter-grid ${showFilters?'expanded':''}`}><label className="field"><span>De</span><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label className="field"><span>Até</span><input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><label className="field"><span>Categoria</span><select value={category} onChange={e=>setCategory(e.target.value)}><option value="">Todas</option>{data.categories.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></label><label className="field"><span>Status</span><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos</option><option value="paid">Pago</option><option value="pending">Pendente</option><option value="overdue">Atrasado</option></select></label><label className="field"><span>Forma de pagamento</span><select value={method} onChange={e=>setMethod(e.target.value)}><option value="">Todas</option>{[['cash','Dinheiro'],['pix','Pix'],['debit','Débito'],['credit','Crédito'],['boleto','Boleto'],['transfer','Transferência'],['voucher','Vale']].map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label><label className="field"><span>Conta</span><select value={account} onChange={e=>setAccount(e.target.value)}><option value="">Todas</option>{data.accounts.map(a=><option value={a.id} key={a.id}>{a.name}</option>)}</select></label><label className="field"><span>Valor mínimo</span><input type="number" min="0" step="0.01" value={min} onChange={e=>setMin(e.target.value)}/></label><label className="field"><span>Valor máximo</span><input type="number" min="0" step="0.01" value={max} onChange={e=>setMax(e.target.value)}/></label></div>
      {!!data.filters.length&&<div className="favorite-filters"><span>Favoritos:</span>{data.filters.map(f=><span className="saved-filter" key={f.id}><button onClick={()=>{const x=f.filters;setQ(x.q??'');setCategory(x.category??'');setStatus(x.status??'');setMethod(x.method??'');setAccount(x.account??'');setFrom(x.from??'');setTo(x.to??'');setMin(x.min??'');setMax(x.max??'');}}>{f.name}</button><button title="Remover filtro" onClick={()=>onDeleteFilter(f.id)}><X size={12}/></button></span>)}</div>}
    </section>
    <section className="panel list-panel"><div className="list-summary"><strong>{filtered.length} lançamentos</strong><span className="muted">{currency(filtered.reduce((s,t)=>s+(t.kind==='income'?-t.amountCents:t.amountCents),0),hidden)} em despesas líquidas</span></div>{filtered.length?filtered.sort((a,b)=>b.date.localeCompare(a.date)).map(tx=><TxRow key={tx.id} tx={tx} categories={data.categories} hidden={hidden} onEdit={()=>onEditEntry(tx)} onDelete={()=>onDeleteEntry(tx)} onPay={()=>onPayEntry(tx)} onRule={()=>onCreateRule(tx)}/>):<Empty title="Nada encontrado" body="Ajuste os filtros ou registre um novo lançamento." action={<button className="btn primary" onClick={onNew}><Plus size={16}/> Novo lançamento</button>}/>}</section>
  </div>;
}

function Budgets({data,month,hidden,onNew,onCopy,onSuggest,onMonthChange}:{data:Data;month:string;hidden:boolean;onNew:()=>void;onCopy:()=>void;onSuggest:()=>void;onMonthChange:(v:string)=>void}){
  const days=monthDays(month);const now=new Date();const left=month===monthKey()?Math.max(0,days-now.getDate()):days;const rows=data.categories.filter(c=>c.kind==='expense'&&!c.archived).map(c=>{const budget=data.budgets.find(b=>b.month===month&&b.categoryId===c.id);const spent=currentBudgetUse(data.transactions,month,c.id,data.receivables);return {category:c,budget:budget?.amountCents??0,spent,remaining:(budget?.amountCents??0)-spent,used:budget?.amountCents?Math.round(spent*100/budget.amountCents):0};}).filter(x=>x.budget>0||x.spent>0);
  return <div className="page-content"><PageTitle eyebrow="PLANEJAMENTO MENSAL" title="Orçamento" desc="Defina limites que acompanham seu ritmo." actions={<MonthPicker month={month} onChange={onMonthChange}/>}/><div className="toolbar-row"><button className="btn primary" onClick={onNew}><Plus size={16}/> Definir categoria</button><button className="btn secondary" onClick={onCopy}><ArrowLeftRight size={15}/> Copiar mês anterior</button><button className="btn secondary" onClick={onSuggest}><Sparkles size={15}/> Sugerir pela média de 3 meses</button></div><div className="budget-cards">{rows.length?rows.map(({category,budget,spent,remaining,used})=><article className={`budget-card ${used>=100?'over':used>=80?'warn':''}`} key={category.id}><div className="budget-head"><span className="category-dot" style={{background:category.color}}/><div><strong>{category.name}</strong><small>{budget?`${used}% consumido`:'Sem limite definido'}</small></div><span className="budget-amount">{currency(spent,hidden)} <small>/ {currency(budget,hidden)}</small></span></div><div className="progress-track"><i style={{width:`${Math.min(100,Math.max(2,used))}%`,background:used>=100?'#D96D5B':used>=80?'#E5A548':category.color}}/></div><div className="budget-foot"><span>{budget?remaining>=0?`${currency(remaining,hidden)} restantes`:`${currency(Math.abs(remaining),hidden)} acima do limite`:'Defina um valor mensal'}</span><span>{budget?`Até ${currency(Math.max(0,remaining)/Math.max(1,left),hidden)} por dia`:`${left} dias restantes`}</span></div>{used>=80&&<div className={`budget-alert ${used>=100?'danger':'warning'}`}><CircleAlert size={14}/>{used>=100?'Limite ultrapassado':`Atenção: ${used}% do limite utilizado`}</div>}</article>):<Empty title="Seu orçamento começa com uma categoria" body="Defina valores mensais e acompanhe o gasto, o restante e o ritmo diário." action={<button className="btn primary" onClick={onNew}><Plus size={16}/> Criar orçamento</button>}/>}</div></div>;
}

function Planning({data,month,hidden,onNewPlan,onConvert}:{data:Data;month:string;hidden:boolean;onNewPlan:()=>void;onConvert:(p:PlannedExpense)=>void}){
  const forecast=buildForecast(month,data);const [what,setWhat]=useState('');const [whatAmount,setWhatAmount]=useState('300');const [whatType,setWhatType]=useState<'cut'|'income'>('cut');
  const sim=useMemo(()=>{const x=Number(whatAmount.replace(',','.'))*100;return forecast.map((row,i)=>{const balance=row.balance+(what?((whatType==='income'?x:-x)*(i+1)):0);return {...row,balance,negative:balance<0};});},[forecast,what,whatAmount,whatType]);
  const planned=data.planned.filter(p=>!p.convertedTransactionId).sort((a,b)=>a.month.localeCompare(b.month));
  return <div className="page-content"><PageTitle eyebrow="OLHE ADIANTE" title="Planejamento" desc="Antecipe compromissos e enxergue o efeito das escolhas." actions={<button className="btn primary" onClick={onNewPlan}><Plus size={16}/> Planejar gasto</button>}/><section className="panel forecast-panel"><SectionTitle title="Saldo projetado · 12 meses" action={<span className="muted tiny">estimativa local</span>}/><ResponsiveContainer width="100%" height={280}><LineChart data={sim} margin={{left:8,right:16,top:12,bottom:5}}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="label" tick={{fontSize:11}}/><YAxis tickFormatter={v=>hidden?'••':`R$${v}`} tick={{fontSize:10}}/><Tooltip formatter={(v:number)=>hidden?'••••':money(Math.round(v*100))}/><Line type="monotone" dataKey="balance" name="Saldo projetado" stroke="#2E755B" strokeWidth={3} dot={{r:3}}/></LineChart></ResponsiveContainer><div className="forecast-strip">{sim.filter(x=>x.negative).map(x=><span key={x.month} className="forecast-negative"><CircleAlert size={14}/>{monthLabel(x.month)} pode ficar negativo</span>)}{!sim.some(x=>x.negative)&&<span className="muted">Nenhum saldo mensal negativo projetado com os dados atuais.</span>}</div></section>
    <section className="panel simulator-panel"><SectionTitle title="Simulador “e se”" action={<Sparkles size={17} className="accent-icon"/>}/><p className="muted">Teste uma mudança sem alterar seus registros reais.</p><div className="simulator-controls"><label className="field"><span>Cenário</span><input value={what} onChange={e=>setWhat(e.target.value)} placeholder="Ex.: Reduzir restaurantes"/></label><label className="field"><span>Tipo</span><select value={whatType} onChange={e=>setWhatType(e.target.value as 'cut'|'income')}><option value="cut">Corte mensal</option><option value="income">Aumento de renda</option></select></label><label className="field"><span>Valor mensal</span><input inputMode="decimal" value={whatAmount} onChange={e=>setWhatAmount(e.target.value)}/></label></div>{what&&<p className="sim-result">{whatType==='cut'?'Cortar':'Adicionar'} {currency(Number(whatAmount.replace(',','.'))*100,hidden)} por mês altera a projeção de 12 meses em até {currency(Number(whatAmount.replace(',','.'))*1200,hidden)}.</p>}</section>
    <section className="panel planned-panel"><SectionTitle title="Gastos previstos" action={<span className="muted tiny">{planned.length} abertos</span>}/>{planned.length?planned.map(p=><div className="planned-row" key={p.id}><div><strong>{p.name}</strong><small>{monthLabel(p.month)} · {categoryFor(p.categoryId,data.categories)?.name??'Outros'}</small></div><b>{currency(p.amountCents,hidden)}</b><button className="btn secondary small" onClick={()=>onConvert(p)}>Converter em lançamento</button></div>):<div className="chart-empty">Adicione viagem, matrícula, presente ou manutenção para refletir na projeção.</div>}</section>
  </div>;
}

function More({onNavigate,onNew}:{onNavigate:(s:Screen)=>void;onNew:(k:ModalKind)=>void}){
  const links:[Screen,string,string,LucideIcon][]=[['accounts','Contas','Saldos, carteira e ajustes',Landmark],['cards','Cartões','Limites, faturas e compras',CreditCardIcon],['recurring','Recorrentes','Fixos, variáveis e vencimentos',Repeat2],['debts','Dívidas','Parcelas e quitação',Activity],['goals','Metas','Aportes, reserva e objetivos',FolderKanban],['receivables','A receber','Divisões e reembolsos',HeartHandshake],['calendar','Calendário','Vencimentos do mês',CalendarDays],['categories','Categorias','Editar grupos e subcategorias',BookOpen],['rules','Regras','Categorização automática',Sparkles],['trash','Lixeira','Itens excluídos por 30 dias',Trash2],['settings','Configurações','Privacidade, tema e backup',Settings2]];
  return <div className="page-content"><PageTitle eyebrow="ORGANIZE SUA VIDA FINANCEIRA" title="Mais" desc="Ajustes e módulos para manter tudo em ordem."/><div className="module-grid">{links.map(([screen,title,subtitle,Icon])=><button className="module-card" key={screen} onClick={()=>onNavigate(screen)}><span className="module-icon"><Icon size={19}/></span><span><strong>{title}</strong><small>{subtitle}</small></span><ArrowRight size={17} className="module-arrow"/></button>)}</div><section className="panel quick-create"><SectionTitle title="Adicionar rapidamente"/><div className="toolbar-row"><button className="btn secondary" onClick={()=>onNew('account')}><Plus size={15}/> Conta</button><button className="btn secondary" onClick={()=>onNew('card')}><Plus size={15}/> Cartão</button><button className="btn secondary" onClick={()=>onNew('recurring')}><Plus size={15}/> Recorrente</button><button className="btn secondary" onClick={()=>onNew('goal')}><Plus size={15}/> Meta</button></div></section></div>;
}

function Accounts({data,hidden,onNew,onArchive,onAdjustment}:{data:Data;hidden:boolean;onNew:()=>void;onArchive:(a:Account)=>void;onAdjustment:()=>void}){
 const balances=accountBalances(data.accounts,data.transactions);return <div className="page-content"><PageTitle eyebrow="CARTEIRA" title="Contas" desc="Saldos por conta, sem apagar seu histórico." actions={<button className="btn primary" onClick={onNew}><Plus size={16}/> Adicionar conta</button>}/><div className="toolbar-row"><button className="btn secondary" onClick={onAdjustment}><SlidersHorizontal size={15}/> Ajustar saldo real</button></div>{data.accounts.length?<div className="account-grid">{data.accounts.map(a=><article className={`account-card ${a.archived?'archived':''}`} key={a.id}><div className="account-card-top"><span className="module-icon" style={{background:`${a.color}22`,color:a.color}}><Landmark size={19}/></span><button className="icon-button" onClick={()=>onArchive(a)} title={a.archived?'Reativar':'Arquivar'}>{a.archived?<RotateCcw size={16}/>:<Archive size={16}/>}</button></div><small>{({checking:'Conta corrente',savings:'Poupança',cash:'Dinheiro físico',investment:'Investimento',meal:'Vale-refeição'} as Record<Account['type'],string>)[a.type]}{a.archived?' · Arquivada':''}</small><h3>{a.name}</h3><strong className="account-balance">{currency(balances[a.id]??a.initialBalanceCents,hidden)}</strong><span className="muted tiny">{a.includeInTotal?'Incluída no saldo total':'Oculta do saldo total'}</span></article>)}</div>:<Empty title="Cadastre sua primeira conta" body="Adicione saldo inicial e decida quais contas entram no total." action={<button className="btn primary" onClick={onNew}><Plus size={16}/> Adicionar conta</button>}/>}</div>;
}

function Cards({data,month,hidden,onNew,onPay,onArchive}:{data:Data;month:string;hidden:boolean;onNew:()=>void;onPay:(i:Invoice)=>void;onArchive:(c:CreditCard)=>void}){
 const invoices=buildInvoices(data.cards,data.transactions);return <div className="page-content"><PageTitle eyebrow="CRÉDITO E FATURAS" title="Cartões" desc="Acompanhe o limite comprometido e as faturas." actions={<button className="btn primary" onClick={onNew}><Plus size={16}/> Adicionar cartão</button>}/>{data.cards.length?<>{data.cards.filter(c=>!c.archived).map(card=>{const own=invoices.filter(i=>i.cardId===card.id);const outstanding=own.reduce((s,i)=>s+i.remainingCents,0);const future=own.filter(i=>i.month>month).reduce((s,i)=>s+i.remainingCents,0);return <section className="panel card-panel" key={card.id}><div className="credit-card-visual" style={{background:card.color}}><div><small>{card.brand}</small><strong>{card.name}</strong></div><span>••••</span><small>FECHAMENTO {card.closingDay} · VENCIMENTO {card.dueDay}</small></div><div className="card-summary"><div><small>Disponível</small><strong>{currency(Math.max(0,card.limitCents-outstanding),hidden)}</strong></div><div><small>Limite total</small><strong>{currency(card.limitCents,hidden)}</strong></div><div><small>Compromisso futuro</small><strong>{currency(future,hidden)}</strong></div><button className="icon-button" onClick={()=>onArchive(card)} title="Arquivar cartão"><Archive size={16}/></button></div><div className="progress-track"><i style={{width:`${card.limitCents?Math.min(100,outstanding*100/card.limitCents):0}%`,background:card.color}}/></div><h3 className="subheading">Faturas</h3>{own.sort((a,b)=>b.month.localeCompare(a.month)).map(inv=><div className="invoice-row" key={inv.id}><div><strong>{monthLabel(inv.month)}</strong><small>{inv.purchases.length} compras · vencimento {formatDate(inv.dueDate)}</small><div className="invoice-purchase-list">{inv.purchases.map(p=><small className="invoice-purchase" key={p.id}>{p.description}{p.installmentIndex&&p.installmentCount?` · ${p.installmentIndex}/${p.installmentCount}`:''} · {formatDate(p.date)} · {currency(p.amountCents,hidden)}</small>)}</div></div><div><b>{currency(inv.totalCents,hidden)}</b><Pill tone={inv.status==='paid'?'success':inv.status==='partial'?'warning':inv.status==='closed'?'neutral':'info'}>{({open:'Aberta',closed:'Fechada',paid:'Paga',partial:'Paga parcialmente'} as Record<Invoice['status'],string>)[inv.status]}</Pill></div>{inv.remainingCents>0&&<button className="btn secondary small" onClick={()=>onPay(inv)}>Pagar fatura</button>}</div>)}{!own.length&&<p className="muted">Nenhuma compra lançada neste cartão.</p>}</section>;})}</>:<Empty title="Adicione um cartão" body="As compras serão agrupadas automaticamente conforme fechamento e vencimento." action={<button className="btn primary" onClick={onNew}><Plus size={16}/> Novo cartão</button>}/>}</div>;
}

function Recurring({data,hidden,onNew,onToggle,onEdit,onPay}:{data:Data;hidden:boolean;onNew:()=>void;onToggle:(r:RecurringItem)=>void;onEdit:(t:Transaction)=>void;onPay:(t:Transaction)=>void}){
 const freqFactor={weekly:4.33,fortnightly:2.17,monthly:1,bimonthly:.5,quarterly:1/3,semiannual:1/6,annual:1/12};const monthly=data.recurring.filter(r=>r.active).reduce((s,r)=>s+r.amountCents*freqFactor[r.frequency],0);const label=(f:RecurringItem['frequency'])=>({weekly:'Semanal',fortnightly:'Quinzenal',monthly:'Mensal',bimonthly:'Bimestral',quarterly:'Trimestral',semiannual:'Semestral',annual:'Anual'})[f];
 return <div className="page-content"><PageTitle eyebrow="COMPROMISSOS FIXOS" title="Recorrentes" desc={`Valor mensal equivalente ${currency(monthly,hidden)} · pagamentos previstos gerados ao abrir o app.`} actions={<button className="btn primary" onClick={onNew}><Plus size={16}/> Novo recorrente</button>}/>{data.recurring.length?data.recurring.map(r=>{const next=data.transactions.filter(t=>t.recurrenceId===r.id&&!t.deletedAt).sort((a,b)=>a.date.localeCompare(b.date)).find(t=>t.status!=='paid');const history=data.transactions.filter(t=>t.recurrenceId===r.id&&!t.deletedAt);const recentPaid=history.filter(t=>t.status==='paid').sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3);const lastSix=history.filter(t=>t.status==='paid').slice(-6);const avg=lastSix.length?lastSix.reduce((s,t)=>s+t.amountCents,0)/lastSix.length:0;return <section className={`panel recurring-row ${!r.active?'paused':''}`} key={r.id}><span className="module-icon"><Repeat2 size={18}/></span><div className="recurring-info"><strong>{r.name}</strong><small>{label(r.frequency)} · {data.categories.find(c=>c.id===r.categoryId)?.name??'Sem categoria'}{r.variable?' · valor variável':''}</small><small>{next?`Próximo: ${formatDate(next.date)} · ${next.status==='overdue'?'atrasado':'pendente'}`:'Sem pendências geradas'} · histórico: {history.length}</small><small>{recentPaid.length?`Últimos pagamentos: ${recentPaid.map(t=>`${formatDate(t.date)} · ${currency(t.amountCents,hidden)}`).join(' · ')}`:'Sem pagamentos registrados'}</small></div><div className="recurring-value"><b>{currency(r.amountCents,hidden)}</b><small>{r.variable&&avg>0?`Média 6m ${currency(Math.round(avg),hidden)}`:'valor previsto'}</small>{r.variable&&next&&avg>0&&next.amountCents>avg&&<small className="recurring-warning">Valor confirmado acima da média dos últimos 6 meses</small>}</div><div className="row-actions">{next&&<button className="icon-button" title="Editar valor/confirmar" onClick={()=>onEdit(next)}><Pencil size={15}/></button>}{next&&<button className="icon-button" title="Marcar pago" onClick={()=>onPay(next)}><Check size={15}/></button>}<button className="btn secondary small" onClick={()=>onToggle(r)}>{r.active?'Pausar':'Retomar'}</button></div></section>; }):<Empty title="Automatize suas contas fixas" body="Salário, aluguel, energia, academia e anuidades: uma vez cadastrados, aparecem como pendentes no mês." action={<button className="btn primary" onClick={onNew}><Plus size={16}/> Cadastrar recorrente</button>}/>}</div>;
}

function Debts({data,hidden,onNew,onPay}:{data:Data;hidden:boolean;onNew:()=>void;onPay:(d:Debt)=>void}){
 const [order,setOrder]=useState<'rate'|'balance'>('rate');const sorted=[...data.debts].filter(d=>d.active).sort((a,b)=>order==='rate'?b.monthlyRateBps-a.monthlyRateBps:a.balanceCents-b.balanceCents);const total=sorted.reduce((s,d)=>s+d.balanceCents,0);const monthly=sorted.reduce((s,d)=>s+d.installmentCents,0);const income=data.transactions.filter(t=>t.kind==='income'&&t.date.startsWith(monthKey())).reduce((s,t)=>s+t.amountCents,0);const commitment=income?Math.round(monthly*100/income):0;
 return <div className="page-content"><PageTitle eyebrow="PLANO DE QUITAÇÃO" title="Dívidas" desc="Veja o saldo, o custo mensal e uma ordem para avançar." actions={<button className="btn primary" onClick={onNew}><Plus size={16}/> Nova dívida</button>}/><div className="stats-grid"><StatCard label="Saldo devedor" value={total} icon={CreditCardIcon} tone="rose" hidden={hidden}/><StatCard label="Parcelas mensais" value={monthly} icon={CalendarDays} tone="amber" hidden={hidden}/><article className="stat-card lavender"><div className="stat-top"><span>Renda comprometida</span><Activity size={17}/></div><strong>{hidden?'•••':`${commitment}%`}</strong><small>sobre a renda registrada neste mês</small></article></div><section className="panel debt-list"><div className="section-title"><h2>Ordem sugerida</h2><div className="segmented"><button className={order==='rate'?'selected':''} onClick={()=>setOrder('rate')}>Maior juros</button><button className={order==='balance'?'selected':''} onClick={()=>setOrder('balance')}>Menor saldo</button></div></div>{sorted.length?sorted.map((d,i)=>{const paid=Math.max(0,d.originalCents-d.balanceCents);const totalPaid=paid+d.interestPaidCents;const remainingInstallments=Math.max(0,d.installmentCount-d.paidInstallments);const progress=d.originalCents?Math.min(100,paid*100/d.originalCents):0;return <article className="debt-row" key={d.id}><span className="rank">{i+1}</span><div className="debt-info"><strong>{d.name}</strong><small>{d.creditor} · {d.kind} · {d.monthlyRateBps/100}% ao mês</small><div className="progress-track"><i style={{width:`${progress}%`}}/></div><small>{d.paidInstallments}/{d.installmentCount} parcelas · {Math.round(progress)}% quitado · {remainingInstallments} restantes</small><small>Total pago {currency(totalPaid,hidden)} · juros pagos {currency(d.interestPaidCents,hidden)}</small></div><div className="debt-values"><b>{currency(d.balanceCents,hidden)}</b><small>parcela {currency(d.installmentCents,hidden)}</small></div><button className="btn secondary small" onClick={()=>onPay(d)}>Registrar parcela</button></article>; }):<Empty title="Cadastre suas dívidas" body="O app sugere a ordem de quitação por juros ou saldo e acompanha o progresso." action={<button className="btn primary" onClick={onNew}><Plus size={16}/> Adicionar dívida</button>}/>}</section></div>;
}

function Goals({data,hidden,onNew,onDeposit,onEdit,onDelete,onArchive}:{data:Data;hidden:boolean;onNew:()=>void;onDeposit:()=>void;onEdit:(g:Goal)=>void;onDelete:(g:Goal)=>void;onArchive:(g:Goal)=>void}) {
  const [monthly,setMonthly]=useState('300');
  const [showArchived,setShowArchived]=useState(false);
  const goals=data.goals.filter(g=>Boolean(g.archived)===showArchived);
  return <div className="page-content">
    <PageTitle eyebrow="SEUS OBJETIVOS" title="Metas" desc="Acompanhe o progresso e ajuste o ritmo de cada objetivo." actions={<>
      <button className="btn secondary" onClick={()=>setShowArchived(!showArchived)}>{showArchived?'Ver metas ativas':'Metas arquivadas'}</button>
      {!showArchived&&<button className="btn secondary" onClick={onDeposit}><ArrowDownLeft size={15}/> Aporte ou resgate</button>}
      {!showArchived&&<button className="btn primary" onClick={onNew}><Plus size={16}/> Nova meta</button>}
    </>}/>
    {goals.length?<div className="goal-grid">{goals.map(g=>{
      const total=goalBalanceCents(g.id,data.transactions);
      const p=g.targetCents?Math.min(100,Math.max(0,total*100/g.targetCents)):0;
      const left=Math.max(0,g.targetCents-total);
      const months=g.deadline?Math.max(1,Math.ceil((new Date(g.deadline).getTime()-Date.now())/(30*86400000))):0;
      const needed=months?Math.ceil(left/months):0;
      const per=Number(monthly.replace(',','.'))*100;
      const eta=per>0?Math.ceil(left/per):0;
      const symbol:Record<string,string>={Alvo:'◎',Casa:'⌂',Estrela:'✦',Viagem:'↗',Reserva:'◌',Carro:'⌁',Estudo:'▤'};
      return <article className="panel goal-card" key={g.id}>
        <div className="goal-top"><span className="goal-symbol">{symbol[g.icon]??'✦'}</span><Pill tone={g.archived?'neutral':g.priority==='high'?'danger':'neutral'}>{g.archived?'Arquivada':g.priority==='high'?'Prioridade alta':g.priority==='low'?'Baixa':'Média'}</Pill></div>
        <h3>{g.name}</h3><div className="goal-progress"><strong>{currency(total,hidden)}</strong><span>de {currency(g.targetCents,hidden)}</span></div>
        <div className="progress-track"><i style={{width:`${p}%`}}/></div><div className="budget-foot"><span>{Math.round(p)}% concluído</span><span>{g.deadline?`Prazo ${formatDate(g.deadline)}`:'Sem prazo'}</span></div>
        {g.deadline&&<p className="goal-pace">{needed>0?`Para cumprir o prazo: ${currency(needed,hidden)}/mês.`:'Meta no ritmo.'}</p>}
        {!g.archived&&<div className="goal-simulator"><label className="field"><span>Se guardar por mês</span><input inputMode="decimal" value={monthly} onChange={e=>setMonthly(e.target.value)}/></label><small>{eta?`Você atinge em cerca de ${eta} ${eta===1?'mês':'meses'}.`:'Informe um valor mensal para simular.'}</small></div>}
        <div className="row-actions goal-actions">
          <button className="icon-button" aria-label={`Editar meta ${g.name}`} title="Editar meta" onClick={()=>onEdit(g)}><Pencil size={15}/></button>
          <button className="icon-button" aria-label={g.archived?`Reativar meta ${g.name}`:`Concluir ou arquivar meta ${g.name}`} title={g.archived?'Reativar meta':'Concluir/arquivar'} onClick={()=>onArchive(g)}>{g.archived?<RotateCcw size={15}/>:<Archive size={15}/>}</button>
          <button className="icon-button danger-icon" aria-label={`Excluir meta ${g.name}`} title="Excluir meta e movimentos para a lixeira" onClick={()=>onDelete(g)}><Trash2 size={15}/></button>
        </div>
        {!g.archived&&<button className="btn secondary small full-btn" onClick={onDeposit}>Registrar aporte ou resgate</button>}
      </article>;
    })}</div>:<Empty title={showArchived?'Nenhuma meta arquivada':'Escolha algo que importa'} body={showArchived?'As metas arquivadas aparecerão aqui.':'Viagem, reserva de emergência ou quitar dívida: acompanhe aportes e prazo em um só lugar.'} action={!showArchived?<button className="btn primary" onClick={onNew}><Plus size={16}/> Criar meta</button>:undefined}/>}
  </div>;
}
function Calendar({data,month,hidden,onPayEntry,onPayInvoice,onMonthChange}:{data:Data;month:string;hidden:boolean;onPayEntry:(t:Transaction)=>void;onPayInvoice:(i:Invoice)=>void;onMonthChange:(v:string)=>void}){
 const [selected,setSelected]=useState('');
 const [y,m]=month.split('-').map(Number); const first=new Date(y,m-1,1).getDay(); const days=monthDays(month); const cells=Array.from({length:42},(_,i)=>i-first+1); const invoices=buildInvoices(data.cards,data.transactions);
 const dueItems=(day:number)=>{ const date=`${month}-${String(day).padStart(2,'0')}`; const items:{id:string;title:string;amount:number;status:string;entry?:Transaction;invoice?:Invoice}[]=data.transactions.filter(t=>!t.deletedAt&&t.dueDate===date).map(t=>({id:t.id,title:t.description,amount:t.amountCents,status:t.status,entry:t})); items.push(...invoices.filter(i=>i.dueDate===date&&i.remainingCents>0).map(i=>({id:i.id,title:`Fatura · ${data.cards.find(c=>c.id===i.cardId)?.name}`,amount:i.remainingCents,status:'pending',invoice:i}))); return items; }; const onSelected=selected?dueItems(Number(selected)):[];
 return <div className="page-content"><PageTitle eyebrow="AGENDA FINANCEIRA" title="Calendário" desc="Vencimentos, parcelas, recorrências, dívidas e aportes por dia." actions={<MonthPicker month={month} onChange={onMonthChange}/>}/><section className="panel calendar-panel"><div className="calendar-grid weekday-row">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=><span key={x}>{x}</span>)}</div><div className="calendar-grid">{cells.map((day,i)=>day<1||day>days?<span className="calendar-blank" key={i}/>:<button key={i} className={`calendar-day ${selected===String(day)?'selected':''} ${todayISO()===`${month}-${String(day).padStart(2,'0')}`?'today':''}`} onClick={()=>setSelected(String(day))}><span>{day}</span>{dueItems(day).length>0&&<i/>}<small>{dueItems(day).length||''}</small></button>)}</div></section><section className="panel selected-day-panel"><SectionTitle title={selected?`${selected} de ${monthLabel(month)}`:'Selecione um dia'} action={selected&&<button className="text-button" onClick={()=>setSelected('')}>Limpar</button>}/>{onSelected.length?onSelected.map(item=><div className="upcoming-item" key={item.id}><span className="date-chip">{selected}</span><div><strong>{item.title}</strong><small>Vencimento</small></div><b>{currency(item.amount,hidden)}</b>{'entry'in item&&item.entry?<button className="btn secondary small" onClick={()=>onPayEntry(item.entry!)}>Marcar pago</button>:'invoice'in item&&item.invoice?<button className="btn secondary small" onClick={()=>onPayInvoice(item.invoice!)}>Pagar</button>:null}</div>):<p className="muted">{selected?'Nenhum compromisso neste dia.':'Toque em um dia com ponto para abrir os itens.'}</p>}</section></div>;
}


function Categories({data,onNew,onEdit}:{data:Data;onNew:()=>void;onEdit:(c:Category)=>void}){return <div className="page-content"><PageTitle eyebrow="PERSONALIZE" title="Categorias" desc="Grupos e subcategorias para classificar os seus lançamentos." actions={<button className="btn primary" onClick={onNew}><Plus size={16}/> Nova categoria</button>}/><div className="category-columns">{(['expense','income'] as const).map(kind=><section className="panel" key={kind}><SectionTitle title={kind==='expense'?'Despesas':'Receitas'}/>{data.categories.filter(c=>c.kind===kind).map(c=><div className="category-row" key={c.id}><i style={{background:c.color}}/><div><strong>{c.name}</strong><small>{c.subcategories.length?c.subcategories.join(' · '):'Sem subcategorias'}</small></div><button className="icon-button" onClick={()=>onEdit(c)} title="Editar"><Pencil size={15}/></button></div>)}</section>)}</div></div>;}


function Rules({data,onDelete}:{data:Data;onDelete:(r:BudgetRule)=>void}){return <div className="page-content"><PageTitle eyebrow="AUTOMAÇÃO LOCAL" title="Regras de categorização" desc="Descrições reconhecidas recebem categoria e forma de pagamento automaticamente."/><section className="panel">{data.rules.length?data.rules.map(r=><div className="category-row" key={r.id}><span className="module-icon"><Sparkles size={16}/></span><div><strong>Se contém “{r.contains}”</strong><small>→ {data.categories.find(c=>c.id===r.categoryId)?.name??'Categoria removida'}{r.paymentMethod?` · ${r.paymentMethod}`:''}</small></div><button className="icon-button danger-icon" onClick={()=>onDelete(r)}><Trash2 size={15}/></button></div>):<Empty title="Sem regras salvas" body="Ao categorizar uma compra manualmente, você pode salvar uma regra para importações futuras."/>}</section></div>;}


function Settings({data,hidden,onTogglePrivacy,onTheme,onMonthStart,onNotifications,onImport,onBackup,onRestoreBackup,onExportPdf}:{data:Data;hidden:boolean;onTogglePrivacy:()=>void;onTheme:(t:'light'|'dark')=>void;onMonthStart:(d:number)=>void;onNotifications:()=>void;onImport:()=>void;onBackup:()=>void;onRestoreBackup:(f:File)=>void;onExportPdf:()=>void}){
 const [quota,setQuota]=useState<{usage?:number;quota?:number}>({});const s=data.settings;const backupDue=!s?.lastBackupReminder||Date.now()-new Date(s.lastBackupReminder).getTime()>30*86400000;
 async function estimate(){try{const e=await navigator.storage?.estimate();setQuota({usage:e?.usage,quota:e?.quota});}catch{setQuota({});}}
 return <div className="page-content"><PageTitle eyebrow="PREFERÊNCIAS LOCAIS" title="Configurações" desc="Ajuste a experiência e proteja seus dados neste dispositivo."/><section className="panel settings-panel"><div className="setting-row"><div><strong>Modo privacidade</strong><small>Oculta os valores financeiros nas telas.</small></div><button className="btn secondary" onClick={onTogglePrivacy}>{hidden?<Eye size={15}/>:<EyeOff size={15}/>} {hidden?'Desativar':'Ativar'}</button></div><div className="setting-row"><div><strong>Tema</strong><small>Preferência salva neste navegador.</small></div><select className="inline-select" value={s?.theme??'light'} onChange={e=>onTheme(e.target.value as 'light'|'dark')}><option value="light">Claro</option><option value="dark">Escuro</option></select></div><div className="setting-row"><div><strong>Primeiro dia do mês financeiro</strong><small>Útil se seu ciclo começa no dia do salário.</small></div><select className="inline-select" value={s?.monthStartDay??1} onChange={e=>onMonthStart(Number(e.target.value))}>{Array.from({length:28},(_,i)=><option key={i+1} value={i+1}>Dia {i+1}</option>)}</select></div><div className="setting-row"><div><strong>Notificações locais</strong><small>Permite alertas ao abrir o app; o PWA fechado não agenda lembretes de forma confiável em todos os sistemas.</small></div><button className="btn secondary" onClick={onNotifications}><Bell size={15}/> {s?.notificationsEnabled?'Desativar':'Ativar'}</button></div><div className="setting-row"><div><strong>Uso do armazenamento</strong><small>{quota.usage&&quota.quota?`${(quota.usage/1024/1024).toFixed(1)} MB de ${(quota.quota/1024/1024).toFixed(0)} MB estimados`: 'A capacidade depende do navegador e do espaço disponível.'}</small></div><button className="btn secondary" onClick={()=>void estimate()}>Consultar</button></div></section><section className="panel settings-panel"><SectionTitle title="Backup e exportação" action={backupDue&&<Pill tone="warning">Lembrete de backup</Pill>}/><p className="muted">Os dados ficam só neste navegador. Exporte e guarde uma cópia em local seguro.</p><div className="toolbar-row"><button className="btn primary" onClick={onBackup}><ShieldCheck size={15}/> Baixar backup JSON</button><label className="btn secondary file-button"><RotateCcw size={15}/> Restaurar backup<input type="file" accept=".json,application/json" onChange={e=>{const f=e.target.files?.[0];if(f)onRestoreBackup(f);}}/></label><button className="btn secondary" onClick={onExportPdf}><Download size={15}/> Resumo mensal PDF</button><button className="btn secondary" onClick={onImport}><FileDown size={15}/> Importar CSV/OFX</button></div>{backupDue&&<p className="helper-text">Já faz 30 dias ou mais desde o último registro de backup. Baixe uma cópia para evitar perda se os dados do navegador forem apagados.</p>}</section><section className="privacy-note"><ShieldCheck size={18}/><p><strong>Seus dados não saem daqui.</strong><br/>O app não envia lançamentos, contas ou anexos a um servidor. O backup é um arquivo que você controla.</p></section></div>;}


function Receipts({data,hidden,onNew,onReceive}:{data:Data;hidden:boolean;onNew:()=>void;onReceive:(r:Receivable)=>void}){return <div className="page-content"><PageTitle eyebrow="REEMBOLSOS E DIVISÕES" title="A receber" desc="Valores de terceiros ligados às suas despesas." actions={<button className="btn primary" onClick={onNew}><Plus size={16}/> Adicionar</button>}/>{data.receivables.length?data.receivables.map(r=><article className="panel receivable-row" key={r.id}><span className="module-icon"><HeartHandshake size={18}/></span><div><strong>{r.person}</strong><small>{r.origin==='split'?'Divisão de gasto':'Reembolso'} · {r.description}</small>{r.dueDate&&<small>Previsto {formatDate(r.dueDate)}</small>}</div><b>{currency(r.amountCents-r.receivedCents,hidden)}</b>{r.status!=='received'&&<button className="btn secondary small" onClick={()=>onReceive(r)}>Recebi</button>}</article>):<Empty title="Ainda não há valores a receber" body="Registre despesas divididas, diárias ou adiantamentos." action={<button className="btn primary" onClick={onNew}><Plus size={16}/> Adicionar</button>}/>}</div>;}

export default function Views(props:Props){
 const {screen,data,month,privateMode,onMonthChange,onNew,onImport,onBackup,onRestoreBackup,onExportCsv,onExportPdf,onEditEntry,onDeleteEntry,onPayEntry,onPayInvoice,onReceive,onTogglePrivacy,onTheme,onMonthStart,onNotifications,onArchiveAccount,onToggleRecurring,onCopyBudgets,onSuggestBudgets,onConvertPlan,onRestore,onPurgeTrash,onSaveFilter,onDeleteFilter,onCreateRule,onDeleteRule,onPayDebt,onArchiveCard,onEditGoal,onDeleteGoal,onArchiveGoal}=props;
 if(screen==='dashboard')return <Dashboard data={data} month={month} hidden={privateMode} onMonthChange={onMonthChange} onNew={onNew} onPayEntry={onPayEntry} onPayInvoice={onPayInvoice} onEditEntry={onEditEntry} onDeleteEntry={t=>onDeleteEntry(t)} onCreateRule={onCreateRule} onImport={onImport} onExportPdf={onExportPdf} onBackup={onBackup} onTogglePrivacy={onTogglePrivacy}/>;
 if(screen==='transactions')return <Transactions data={data} month={month} hidden={privateMode} onNew={()=>onNew('entry')} onEditEntry={onEditEntry} onDeleteEntry={onDeleteEntry} onPayEntry={onPayEntry} onCreateRule={onCreateRule} onExportCsv={onExportCsv} onSaveFilter={onSaveFilter} onDeleteFilter={onDeleteFilter}/>;
 if(screen==='budget')return <Budgets data={data} month={month} hidden={privateMode} onNew={()=>onNew('budget')} onCopy={onCopyBudgets} onSuggest={onSuggestBudgets} onMonthChange={onMonthChange}/>;
 if(screen==='planning')return <Planning data={data} month={month} hidden={privateMode} onNewPlan={()=>onNew('plan')} onConvert={onConvertPlan}/>;
 if(screen==='more')return <More onNavigate={props.onNavigate} onNew={onNew}/>;
 if(screen==='accounts')return <Accounts data={data} hidden={privateMode} onNew={()=>onNew('account')} onArchive={onArchiveAccount} onAdjustment={()=>onNew('adjustment')}/>;
 if(screen==='cards')return <Cards data={data} month={month} hidden={privateMode} onNew={()=>onNew('card')} onPay={onPayInvoice} onArchive={onArchiveCard}/>;
 if(screen==='recurring')return <Recurring data={data} hidden={privateMode} onNew={()=>onNew('recurring')} onToggle={onToggleRecurring} onEdit={onEditEntry} onPay={onPayEntry}/>;
 if(screen==='debts')return <Debts data={data} hidden={privateMode} onNew={()=>onNew('debt')} onPay={onPayDebt}/>;
 if(screen==='goals')return <Goals data={data} hidden={privateMode} onNew={()=>onNew('goal')} onDeposit={()=>onNew('deposit')} onEdit={onEditGoal} onDelete={onDeleteGoal} onArchive={onArchiveGoal}/>;
 if(screen==='receivables')return <Receipts data={data} hidden={privateMode} onNew={()=>onNew('receivable')} onReceive={onReceive}/>;
 if(screen==='calendar')return <Calendar data={data} month={month} hidden={privateMode} onPayEntry={onPayEntry} onPayInvoice={onPayInvoice} onMonthChange={onMonthChange}/>;
 if(screen==='trash')return <TrashView items={data.trash} onRestore={onRestore} onPurge={onPurgeTrash}/>;
 if(screen==='categories')return <Categories data={data} onNew={()=>onNew('category')} onEdit={c=>onNew('category',c)}/>;
 if(screen==='rules')return <Rules data={data} onDelete={onDeleteRule}/>;
 if(screen==='settings')return <Settings data={data} hidden={privateMode} onTogglePrivacy={onTogglePrivacy} onTheme={onTheme} onMonthStart={onMonthStart} onNotifications={onNotifications} onImport={onImport} onBackup={onBackup} onRestoreBackup={onRestoreBackup} onExportPdf={onExportPdf}/>;
 return null;
}
